using UnityEngine;
using System.Collections;
using System.Collections.Generic;
public partial class DungeonPrototype {
 public bool LaboratoryReady {get{return view!=null&&inventorySettings!=null;}}
 public bool LaboratoryBusy {get{return busy||moving;}}
 public bool LaboratoryBattle {get{return battle;}}
 public void InitializeLaboratory(){if(GetComponent<CombatLaboratory>()==null||!LaboratoryReady)return;startMenuOpen=saveSlotsOpen=false;SetPause(false);introduction?.Skip();introductionCompleted=true;ReleaseIntroductionInput();message="Elige un enemigo para probar.";}
 public void ResetLaboratory(int level){if(GetComponent<CombatLaboratory>()==null||!LaboratoryReady)return;foreach(var visual in GetComponentsInChildren<MakongEnemyVisual>())visual.EndSpecial();foreach(var hack in GetComponents<CombatHack>()){hack.enabled=false;hack.enabled=true;}var data=CaptureDungeonSave();data.enemies.Clear();data.triggeredEncounters=new string[0];data.introductionCompleted=true;data.player.level=level;data.player.experience=0;data.player.currentHP=int.MaxValue;RestoreDungeonSave(data);startMenuOpen=saveSlotsOpen=false;encounterHomes.Clear();encounterScales.Clear();selectingEnemy=false;pendingTargetHack=null;if(battleStage!=null)battleStage.SetActive(false);SetCeilingReflection(corridorHeight);view.fieldOfView=68;Time.timeScale=1;AudioListener.pause=false;message="Laboratorio de combate";}
 public void StartLaboratoryCombat(string species,int enemyLevel,int gamerLevel,int companions,int equipmentPreset=-1){if(GetComponent<CombatLaboratory>()==null)return;ResetLaboratory(gamerLevel);if(equipmentPreset>=0){for(int slot=0;slot<3;slot++){string id=slot<equipmentPreset?MakongPreparationEquipment.Ids[slot]:Character.initialEquipmentIds[slot];AcquireEquipment(id);EquipItem(id);}hp=MaximumHP;}var group=new List<int>();var region=RegionAt(position);
  for(int n=0;n<1+Mathf.Clamp(companions,0,2);n++){string id=n==0?species:n==1?"Tapaku":"Hongo";var cell=new Vector2Int(3+n,5);var placement=new PlacedEnemyDefinition{id="lab-"+n,speciesId=id,cell=cell,randomLevel=false,fixedLevel=Mathf.Max(1,enemyLevel),allowInSafeArea=true,respawn=false,unique=true,countsTowardLimit=false,category=id=="Makong"?PlacedEnemyCategory.Elite:PlacedEnemyCategory.Normal};int before=enemyObjects.Count;AddEnemy(cell,visualKind:ArrayIndex(id),origin:region,placement:placement);if(enemyObjects.Count>before)group.Add(enemyObjects.Count-1);}
  if(group.Count>0)BeginEncounter(group[0],group);
 }
 public bool LaboratoryMakongSpecial(bool swallow){if(GetComponent<CombatLaboratory>()==null||!battle||busy||lost)return false;int index=encounter.Find(i=>enemyObjects[i]!=null&&enemyObjects[i].GetComponent<MakongEnemyVisual>()!=null);if(index<0)return false;var visual=enemyObjects[index].GetComponent<MakongEnemyVisual>();var action=swallow?MakongAction.Swallow:MakongAction.Earthquake;var context=MakongContextFor(index,visual);if(!visual.Tactics.TryManual(action,context,MakongSpecialSettings.Current)){message="Habilidad no disponible: revisa HP, ayudantes, usos y enfriamiento.";return false;}busy=true;activeEnemy=index;StartCoroutine(LaboratorySpecial(index,swallow));return true;}
 IEnumerator LaboratorySpecial(int index,bool swallow){yield return RunMakongAction(index,enemyObjects[index].GetComponent<MakongEnemyVisual>(),swallow?MakongAction.Swallow:MakongAction.Earthquake);enemyHP=enemyLives[index];busy=false;}
}
